"evidence": [{"part": 1, "relation": "insufficient", "same_entity": false, "same_scope": false, "quote": "believes in a balanced approach in evaluating dams"}, {"part": 2, "relation": "insufficient", "same_entity": false, "same_scope": false, "quote": "examine the potential removal of existing dams on a case-by-case basis"}, {"part": 2, "relation": "insufficient", "same_entity": false, "same_scope": false, "quote": "Important factors to consider when evaluating potential dam removal are whether"}],
"missing_conditions": [{"part": 2, "text": "The source's case-by-case evaluation concerns only the potential removal of existing dams, using factors such as societal benefits, owner agreement, economic sense, and environmental benefits. It does not address time spent on multiple approaches to a task.", "quote": "examine the potential removal of existing dams on a case-by-case basis"}]}

